class Solution {
public:
    int maxPathLength(vector<vector<int>>& coordinates, int k) {
        int n = coordinates.size();
        vector<int> before(n, 1), after(n, 1);
        for (int i = 0; i <= k; i++)
            for (int j = 0; j < i; j++)
                if (coordinates[j][0] < coordinates[i][0] && coordinates[j][1] < coordinates[i][1])
                    before[i] = max(before[i], before[j] + 1);
        for (int i = n - 1; i >= k; i--)
            for (int j = n - 1; j > i; j--)
                if (coordinates[j][0] > coordinates[i][0] && coordinates[j][1] > coordinates[i][1])
                    after[i] = max(after[i], after[j] + 1);
        return before[k] + after[k] - 1;
    }
};

