from bisect import bisect_left
class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        kx, ky = coordinates[k]
        def lis(pts):
            pts.sort(key=lambda p: (p[0], -p[1]))
            tails = []
            for _, y in pts:
                i = bisect_left(tails, y)
                if i == len(tails):
                    tails.append(y)
                else:
                    tails[i] = y
            return len(tails)
        low = [p for p in coordinates if p[0] < kx and p[1] < ky]
        high = [p for p in coordinates if p[0] > kx and p[1] > ky]
        return lis(low) + lis(high) + 1

