class Solution {
public:
    int maxPathLength(vector<vector<int>>& coordinates, int k) {
        int kx = coordinates[k][0], ky = coordinates[k][1];
        vector<pair<int,int>> low, high;
        for (auto& p : coordinates) {
            if (p[0] < kx && p[1] < ky) low.push_back({p[0], p[1]});
            else if (p[0] > kx && p[1] > ky) high.push_back({p[0], p[1]});
        }
        auto lis = [](vector<pair<int,int>>& pts) {
            sort(pts.begin(), pts.end(), [](const pair<int,int>& a, const pair<int,int>& b) {
                return a.first != b.first ? a.first < b.first : a.second > b.second;
            });
            vector<int> tails;
            for (auto& p : pts) {
                auto it = lower_bound(tails.begin(), tails.end(), p.second);
                if (it == tails.end()) tails.push_back(p.second);
                else *it = p.second;
            }
            return (int)tails.size();
        };
        return lis(low) + lis(high) + 1;
    }
};

