class Solution {
    public int maxPathLength(int[][] coordinates, int k) {
        int kx = coordinates[k][0], ky = coordinates[k][1];
        List<int[]> low = new ArrayList<>(), high = new ArrayList<>();
        for (int[] p : coordinates) {
            if (p[0] < kx && p[1] < ky) low.add(p);
            else if (p[0] > kx && p[1] > ky) high.add(p);
        }
        return lis(low) + lis(high) + 1;
    }
    private int lis(List<int[]> pts) {
        pts.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(b[1], a[1]));
        List<Integer> tails = new ArrayList<>();
        for (int[] p : pts) {
            int idx = Collections.binarySearch(tails, p[1]);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(p[1]);
            else tails.set(idx, p[1]);
        }
        return tails.size();
    }
}

