var maxPathLength = function(coordinates, k) {
    const [kx, ky] = coordinates[k];
    const lis = (pts) => {
        pts.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : b[1] - a[1]);
        const tails = [];
        for (const [, y] of pts) {
            let lo = 0, hi = tails.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (tails[mid] < y) lo = mid + 1;
                else hi = mid;
            }
            if (lo === tails.length) tails.push(y);
            else tails[lo] = y;
        }
        return tails.length;
    };
    const low = coordinates.filter(p => p[0] < kx && p[1] < ky);
    const high = coordinates.filter(p => p[0] > kx && p[1] > ky);
    return lis(low) + lis(high) + 1;
};
